#define MOD 1000000007

int modPow(int base, int exp) {
    int result = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) result = (long long)result * base % MOD;
        exp >>= 1;
        base = (long long)base * base % MOD;
    }
    return result;
}

int modInverse(int n) {
    return modPow(n, MOD - 2);
}

